// Author: MiYu. Runtime FDF frame ownership and inherited visibility.
#include "map_frames.h"
#include <algorithm>
#include <array>
#include <cmath>
#include <stdexcept>

namespace war3 {
std::uint32_t modulateMapFrameAlpha(std::uint32_t color,std::uint8_t alpha){return (color&0x00ffffffu)|((((color>>24)*unsigned(alpha)+127)/255)<<24);}
MapFrameRect solveSimpleFrameAnchor(MapFrameRect parent,float width,float height,std::string_view point,float x,float y){static constexpr std::array<std::string_view,9> points={"TOPLEFT","TOP","TOPRIGHT","LEFT","CENTER","RIGHT","BOTTOMLEFT","BOTTOM","BOTTOMRIGHT"};auto found=std::find(points.begin(),points.end(),point);if(found==points.end() || !std::isfinite(parent.x) || !std::isfinite(parent.y) || !std::isfinite(parent.w) || !std::isfinite(parent.h) || !std::isfinite(width) || !std::isfinite(height) || !std::isfinite(x) || !std::isfinite(y) || parent.w<0 || parent.h<0 || width<0 || height<0)throw std::runtime_error("Invalid simple frame anchor");auto index=size_t(found-points.begin());return {parent.x+float(index%3)*.5f*(parent.w-width)+x,parent.y+float(index/3)*.5f*(parent.h-height)-y,width,height};}
MapFrameRect solveMapFramePoints(float width,float height,std::span<const MapFramePoint> points){
    if(points.empty() || !std::isfinite(width) || !std::isfinite(height) || width<0 || height<0)throw std::runtime_error("Invalid map frame layout");
    auto axis=[&](bool vertical,float size){auto coefficient=[&](const MapFramePoint& p){return float(vertical?p.point/3:p.point%3)*.5f;};auto value=[&](const MapFramePoint& p){return vertical?p.y:p.x;};auto first=points.front();if(first.point>8 || !std::isfinite(first.x) || !std::isfinite(first.y))throw std::runtime_error("Invalid map frame point");float c=coefficient(first),v=value(first);bool sized=false;for(auto& p:points){if(p.point>8 || !std::isfinite(p.x) || !std::isfinite(p.y))throw std::runtime_error("Invalid map frame point");float d=coefficient(p)-c;if(d!=0 && !sized){size=(value(p)-v)/d;sized=true;}}if(!std::isfinite(size) || size<0)throw std::runtime_error("Invalid map frame extent");float origin=v-c*size;for(auto& p:points)if(std::abs(origin+coefficient(p)*size-value(p))>1e-5f)throw std::runtime_error("Conflicting map frame anchors");return std::pair{origin,size};};
    auto [x,w]=axis(false,width);auto [y,h]=axis(true,height);return {x,y,w,h};
}
MapFrames::MapFrames(std::shared_ptr<FrameDefinitions> definitions):definitions_(std::move(definitions)){if(!definitions_)throw std::runtime_error("Missing map frame definitions");FrameDefinition root;root.type="FRAME";root.name="GameUI";root.properties["Width"]={"0.8"};root.properties["Height"]={"0.6"};nodes_.emplace(1,Node{1,0,0,std::move(root),true,{},{},{},{}});}
const MapFrames::Node& MapFrames::node(std::uint32_t id) const{auto found=nodes_.find(id);if(found==nodes_.end())throw std::runtime_error("Unknown map frame: "+std::to_string(id));return found->second;}
std::uint32_t MapFrames::add(FrameDefinition definition,std::uint32_t parent,std::uint32_t context,unsigned depth){if(depth>32 || nodes_.size()>=16384 || !next_)throw std::runtime_error("Map frame budget exceeded");auto children=std::move(definition.children);definition.children.clear();auto id=next_++;nodes_.emplace(id,Node{id,parent,context,std::move(definition),true,{},{},{},{}});nodes_.at(parent).children.push_back(id);for(auto& child:children)add(std::move(child),id,context,depth+1);return id;}
std::uint32_t MapFrames::create(const std::string& name,std::uint32_t parent,std::uint32_t context){node(parent);auto definition=definitions_->frame(name);auto staged=*this;auto id=staged.add(std::move(definition),parent,context,0);++staged.revision_;*this=std::move(staged);return id;}
void MapFrames::destroy(std::uint32_t id){if(id==root())throw std::runtime_error("Cannot destroy map UI root");auto parent=node(id).parent;std::vector<std::uint32_t> pending{id};for(size_t i=0;i<pending.size();++i){auto& children=node(pending[i]).children;pending.insert(pending.end(),children.begin(),children.end());}std::set<std::uint32_t> removed(pending.begin(),pending.end());auto& siblings=nodes_.at(parent).children;std::erase(siblings,id);for(auto child:pending){textBytes_-=nodes_.at(child).dynamicTextBytes;textureBytes_-=nodes_.at(child).dynamicTextureBytes;nodes_.erase(child);}for(auto& [key,current]:nodes_)std::erase_if(current.anchors,[&](auto& entry){return removed.contains(entry.second.target);});++revision_;}
void MapFrames::setPoint(std::uint32_t id,std::uint32_t point,std::uint32_t target,std::uint32_t targetPoint,float x,float y){node(id);node(target);if(id==root() || id==target || point>8 || targetPoint>8 || !std::isfinite(x) || !std::isfinite(y))throw std::runtime_error("Invalid map frame anchor");nodes_.at(id).anchors.insert_or_assign(point,Anchor{point,target,targetPoint,x,y});++revision_;}
void MapFrames::clearPoints(std::uint32_t id){node(id);if(id==root())throw std::runtime_error("Cannot clear game UI root anchors");auto& current=nodes_.at(id);if(current.anchors.empty() && current.definition.points.empty() && !current.definition.properties.contains("Anchor") && !current.definition.properties.contains("SetAllPoints"))return;current.anchors.clear();current.definition.points.clear();current.definition.properties.erase("Anchor");current.definition.properties.erase("SetAllPoints");++revision_;}
void MapFrames::setSize(std::uint32_t id,std::optional<float> width,std::optional<float> height){node(id);auto valid=[](std::optional<float> value){return !value || (std::isfinite(*value) && *value>=0);};if(id==root() || (!width && !height) || !valid(width) || !valid(height))throw std::runtime_error("Invalid map frame size");auto& current=nodes_.at(id);if(width)current.width=width;if(height)current.height=height;++revision_;}
void MapFrames::setText(std::uint32_t id,std::string text){auto& current=node(id);constexpr size_t budget=16u*1024u*1024u;if(current.definition.type!="TEXT" || text.size()>65536 || text.find('\0')!=std::string::npos || text.size()>budget-(textBytes_-current.dynamicTextBytes))throw std::runtime_error("Invalid map frame text");auto size=text.size();auto properties=current.definition.properties;properties["Text"]={std::move(text)};properties["RuntimeText"]={};auto& target=nodes_.at(id);target.definition.properties.swap(properties);textBytes_=textBytes_-target.dynamicTextBytes+size;target.dynamicTextBytes=size;++revision_;}
void MapFrames::setTexture(std::uint32_t id,std::string name,bool tiled){auto& current=node(id);constexpr size_t budget=16u*1024u*1024u;if(current.definition.type!="BACKDROP" || name.size()>8192 || name.find('\0')!=std::string::npos || (!name.empty() && (name.front()=='/' || name.front()=='\\' || name.find(':')!=std::string::npos || name.find("..")!=std::string::npos)) || name.size()>budget-(textureBytes_-current.dynamicTextureBytes))throw std::runtime_error("Invalid map frame texture");auto size=name.size();auto properties=current.definition.properties;properties["BackdropBackground"]={std::move(name)};properties["RuntimeTexture"]={};if(tiled)properties["BackdropTileBackground"]={};else properties.erase("BackdropTileBackground");auto& target=nodes_.at(id);target.definition.properties.swap(properties);textureBytes_=textureBytes_-target.dynamicTextureBytes+size;target.dynamicTextureBytes=size;++revision_;}
std::string MapFrames::text(std::uint32_t id) const{auto& current=node(id);if(current.definition.type!="TEXT")throw std::runtime_error("Unsupported map frame text type: "+current.definition.type);auto& values=current.definition.property("Text");auto value=values.empty()?std::string{}:values.front();return current.definition.properties.contains("RuntimeText")?value:definitions_->string(value);}
void MapFrames::setTextColor(std::uint32_t id,std::uint32_t color){auto& current=node(id);if(current.definition.type!="TEXT")throw std::runtime_error("Unsupported map frame text color type: "+current.definition.type);if(textColor(id)==color)return;nodes_.at(id).textColor=color;++revision_;}
std::uint32_t MapFrames::textColor(std::uint32_t id) const{auto& current=node(id);if(current.definition.type!="TEXT")throw std::runtime_error("Unsupported map frame text color type: "+current.definition.type);return current.textColor?*current.textColor:current.definition.color("FontColor",0xffffcc55);}
void MapFrames::setAlpha(std::uint32_t id,std::uint8_t alpha){node(id);if(id==root())throw std::runtime_error("Game UI root alpha is not implemented");auto& current=nodes_.at(id).alpha;if(current && *current==alpha)return;current=alpha;++revision_;}
std::uint8_t MapFrames::alpha(std::uint32_t id) const{node(id);for(unsigned depth=0;id;++depth){if(depth>34)throw std::runtime_error("Invalid map frame hierarchy");auto& current=node(id);if(current.alpha)return *current.alpha;id=current.parent;}return 255;}
void MapFrames::visible(std::uint32_t id,bool value){node(id);auto& current=nodes_.at(id).visible;if(current!=value){current=value;++revision_;}}
bool MapFrames::visible(std::uint32_t id) const{node(id);for(unsigned depth=0;id;++depth){if(depth>34)throw std::runtime_error("Invalid map frame hierarchy");auto& current=node(id);if(!current.visible)return false;id=current.parent;}return true;}
}
